package cn.course.community;
import java.util.*;
import java.math.BigDecimal;
import java.time.Instant;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:workflow;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed=true","app.seed-password=TestOnly!2026Long"})
@AutoConfigureMockMvc @Transactional
class WorkflowIntegrationTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired Store s;@Autowired CommunityService domain;@Autowired NotificationService notices;
 List<QualityCalculator.Item> items(BigDecimal score){return QualityCalculator.CODES.stream().map(c->new QualityCalculator.Item(c,score,"SCORED","")).toList();}
 Map<String,Object> draft(int revision,int base,String summary){return Map.of("items",items(null),"summary",summary,"gateReason","","revision",revision,"baseEvaluationRevision",base);}
 void save(long sid,Map<String,Object> body)throws Exception {mvc.perform(put("/api/submissions/"+sid+"/review-draft").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(body))).andExpect(status().isOk());}
 long countNotices(){return s.db.queryForObject("SELECT COUNT(*) FROM notification",Long.class);}
 long otherTeacher(){long uid=s.insert("INSERT INTO app_user(email,display_name,password_hash) SELECT 'teacher2@example.test','另一位教师',password_hash FROM app_user WHERE email='teacher@example.test'");s.db.update("INSERT INTO course_member(course_id,user_id,role) VALUES(1,?,'TEACHER')",uid);return uid;}
 @Test void partialDraftPersistsPrivatelyWithoutPublishingOrAlert()throws Exception {long before=countNotices();save(2,draft(0,0,"PRIVATE-REVIEW-SECRET"));mvc.perform(get("/api/submissions/2/review-draft").with(user("teacher@example.test"))).andExpect(jsonPath("draft.summary").value("PRIVATE-REVIEW-SECRET")).andExpect(jsonPath("draft.revision").value(1)).andExpect(jsonPath("draft.stale").value(false));String student=mvc.perform(get("/api/submissions/2").with(user("peer@example.test"))).andReturn().getResponse().getContentAsString();assertFalse(student.contains("PRIVATE-REVIEW-SECRET"));assertEquals(0,s.db.queryForObject("SELECT COUNT(*) FROM evaluation WHERE submission_id=2",Integer.class));assertEquals(before,countNotices());}
 @Test void studentsAssistantsAndOtherCoursesCannotReadOrWriteDraft()throws Exception {s.db.update("UPDATE course_member SET role='ASSISTANT' WHERE course_id=1 AND user_id=?",s.uid("peer@example.test"));for(String who:List.of("student","peer","outsider")){mvc.perform(get("/api/submissions/2/review-draft").with(user(who+"@example.test"))).andExpect(status().isForbidden());mvc.perform(put("/api/submissions/2/review-draft").with(user(who+"@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(draft(0,0,"test")))).andExpect(status().isForbidden());}}
 @Test void csrfAndSessionRequiredForPrivateDraft()throws Exception {mvc.perform(get("/api/submissions/2/review-draft")).andExpect(status().isUnauthorized());mvc.perform(put("/api/submissions/2/review-draft").with(user("teacher@example.test")).contentType("application/json").content(json.writeValueAsString(draft(0,0,"test")))).andExpect(status().isForbidden());}
 @Test void staleTabCannotOverwriteDraft()throws Exception {save(2,draft(0,0,"first"));mvc.perform(put("/api/submissions/2/review-draft").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(draft(0,0,"second")))).andExpect(status().isConflict());mvc.perform(get("/api/submissions/2/review-draft").with(user("teacher@example.test"))).andExpect(jsonPath("draft.summary").value("first"));}
 @Test void teachersHaveSeparateDrafts()throws Exception {otherTeacher();save(2,draft(0,0,"private first"));mvc.perform(get("/api/submissions/2/review-draft").with(user("teacher2@example.test"))).andExpect(jsonPath("draft").isEmpty());mvc.perform(put("/api/submissions/2/review-draft").with(user("teacher2@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(draft(0,0,"private second")))).andExpect(status().isOk());assertEquals(2,s.db.queryForObject("SELECT COUNT(*) FROM review_draft WHERE submission_id=2",Integer.class));}
 @Test void formalEvaluationMakesOtherDraftStale()throws Exception {long other=otherTeacher();save(2,draft(0,0,"old"));domain.evaluate(2,new ApiController.EvaluationRequest(items(BigDecimal.valueOf(80)),"","new formal",0),other);mvc.perform(get("/api/submissions/2/review-draft").with(user("teacher@example.test"))).andExpect(jsonPath("draft.stale").value(true)).andExpect(jsonPath("evaluationRevision").value(1));mvc.perform(put("/api/submissions/2/review-draft").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(draft(1,0,"old changed")))).andExpect(status().isConflict());}
 @Test void publishingRemovesOnlyPublishingTeachersDraft()throws Exception {long other=otherTeacher();save(2,draft(0,0,"first"));mvc.perform(put("/api/submissions/2/review-draft").with(user("teacher2@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(draft(0,0,"second")))).andExpect(status().isOk());domain.evaluate(2,new ApiController.EvaluationRequest(items(BigDecimal.valueOf(80)),"","formal",0),s.uid("teacher@example.test"));assertEquals(1,s.db.queryForObject("SELECT COUNT(*) FROM review_draft WHERE submission_id=2 AND teacher_id=?",Integer.class,other));assertEquals(0,s.db.queryForObject("SELECT COUNT(*) FROM review_draft WHERE submission_id=2 AND teacher_id=?",Integer.class,s.uid("teacher@example.test")));}
 @Test void draftDeleteChecksRevisionAndDoesNotDeleteGrade()throws Exception {save(1,draft(0,1,"regrade"));mvc.perform(delete("/api/submissions/1/review-draft").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content("{\"revision\":0}")).andExpect(status().isConflict());mvc.perform(delete("/api/submissions/1/review-draft").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content("{\"revision\":1}")).andExpect(status().isOk());assertEquals(1,s.db.queryForObject("SELECT COUNT(*) FROM evaluation WHERE submission_id=1 AND active=TRUE",Integer.class));}
 @Test void invalidDraftValuesRejected()throws Exception {var invalid=new ArrayList<>(items(null));invalid.set(0,new QualityCalculator.Item("S1",BigDecimal.valueOf(101),"SCORED",""));var body=new HashMap<>(draft(0,0,"bad"));body.put("items",invalid);mvc.perform(put("/api/submissions/2/review-draft").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(body))).andExpect(status().isUnprocessableEntity());invalid.set(0,new QualityCalculator.Item("S2",null,"UNKNOWN",""));mvc.perform(put("/api/submissions/2/review-draft").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(body))).andExpect(status().isUnprocessableEntity());}
 @Test void inboxContainsOnlyOwnSafeMetadata()throws Exception {String raw=mvc.perform(get("/api/notifications").with(user("student@example.test"))).andExpect(status().isOk()).andExpect(jsonPath("unreadCount").isNumber()).andReturn().getResponse().getContentAsString();assertFalse(raw.contains("password_hash"));assertFalse(raw.contains("draft_json"));assertFalse(raw.contains("请补出 ATP"));var data=json.readTree(raw);for(var n:data.path("items"))assertEquals(s.uid("student@example.test"),n.path("recipient_id").asLong());}
 @Test void cannotMarkSomeoneElsesNotification()throws Exception {long id=s.id(s.one("SELECT id FROM notification WHERE recipient_id=? LIMIT 1",s.uid("student@example.test")),"id");mvc.perform(put("/api/notifications/"+id+"/read").with(user("peer@example.test")).with(csrf())).andExpect(status().isNotFound());mvc.perform(put("/api/notifications/"+id+"/read").with(user("student@example.test"))).andExpect(status().isForbidden());for(int i=0;i<2;i++)mvc.perform(put("/api/notifications/"+id+"/read").with(user("student@example.test")).with(csrf())).andExpect(status().isOk());}
 @Test void readAllDoesNotAffectOthers()throws Exception {long teacherUnread=s.db.queryForObject("SELECT COUNT(*) FROM notification WHERE recipient_id=? AND read_at IS NULL",Long.class,s.uid("teacher@example.test"));mvc.perform(put("/api/notifications/read-all").with(user("student@example.test")).with(csrf())).andExpect(status().isOk());mvc.perform(get("/api/notifications?unread=true").with(user("student@example.test"))).andExpect(jsonPath("unreadCount").value(0)).andExpect(jsonPath("items.length()").value(0));assertEquals(teacherUnread,s.db.queryForObject("SELECT COUNT(*) FROM notification WHERE recipient_id=? AND read_at IS NULL",Long.class,s.uid("teacher@example.test")));}
 @Test void notificationsAreKeysetPaginated()throws Exception {long student=s.uid("student@example.test"),teacher=s.uid("teacher@example.test");for(int i=0;i<45;i++)notices.send(student,1,"FEEDBACK","MEMBER","test","submission",1,"",teacher);JsonNode first=json.readTree(mvc.perform(get("/api/notifications").with(user("student@example.test"))).andReturn().getResponse().getContentAsString());assertEquals(20,first.path("items").size());assertTrue(first.path("hasMore").asBoolean());long cursor=first.path("nextCursor").asLong();JsonNode second=json.readTree(mvc.perform(get("/api/notifications?before="+cursor).with(user("student@example.test"))).andReturn().getResponse().getContentAsString());assertEquals(20,second.path("items").size());for(var n:second.path("items"))assertTrue(n.path("id").asLong()<cursor);mvc.perform(get("/api/notifications?before=0").with(user("student@example.test"))).andExpect(status().isBadRequest());}
 @Test void removedMembershipAndDemotionHideNotifications()throws Exception {s.db.update("DELETE FROM course_member WHERE course_id=1 AND user_id=?",s.uid("student@example.test"));mvc.perform(get("/api/notifications").with(user("student@example.test"))).andExpect(jsonPath("items.length()").value(0)).andExpect(jsonPath("unreadCount").value(0));s.db.update("UPDATE course_member SET role='STUDENT' WHERE course_id=1 AND user_id=?",s.uid("teacher@example.test"));mvc.perform(get("/api/notifications").with(user("teacher@example.test"))).andExpect(jsonPath("items.length()").value(0));}
 @Test void idempotentSubmissionDoesNotDuplicateNotifications()throws Exception {long before=countNotices();mvc.perform(post("/api/entries/1/submissions").with(user("student@example.test")).with(csrf()).header("Idempotency-Key","seed-version-one").contentType("application/json").content("{\"revision\":0}")).andExpect(status().isOk());assertEquals(before,countNotices());}
 @Test void failedDomainOperationDoesNotNotify()throws Exception {long before=countNotices();mvc.perform(post("/api/submissions/2/evaluations").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content("{\"items\":[],\"gateReason\":\"\",\"summary\":\"bad\",\"expectedRevision\":0}")).andExpect(status().isUnprocessableEntity());assertEquals(before,countNotices());}
 @Test void evidenceAndPublicationNotifyOnlyRelevantRecipients()throws Exception {long before=countNotices();domain.addFeedback(1,new ApiController.FeedbackRequest("p-gap","C2","new actual event"),s.uid("teacher@example.test"));assertEquals(before+1,countNotices());var n=s.one("SELECT * FROM notification ORDER BY id DESC LIMIT 1");assertEquals(s.uid("student@example.test"),s.id(n,"recipient_id"));assertEquals("p-gap",n.get("anchor_id"));assertEquals("FEEDBACK",n.get("kind"));}
 @Test void deadlineStatesComeWithServerClock()throws Exception {s.db.update("UPDATE assignment SET due_at=? WHERE id=1",Instant.now().plusSeconds(300).toString());mvc.perform(get("/api/courses/1/assignments").with(user("student@example.test"))).andExpect(jsonPath("[0].due_status").value("DUE_SOON")).andExpect(jsonPath("[0].server_now").isString());s.db.update("UPDATE assignment SET due_at=? WHERE id=1",Instant.now().minusSeconds(1).toString());mvc.perform(get("/api/courses/1/assignments").with(user("student@example.test"))).andExpect(jsonPath("[0].due_status").value("CLOSED"));}
 @Test void expiredWorkCanBeSavedButNotSubmitted()throws Exception {s.db.update("UPDATE assignment SET due_at=? WHERE id=1",Instant.now().minusSeconds(1).toString());mvc.perform(post("/api/assignments/1/entries").with(user("student@example.test")).with(csrf())).andExpect(status().isOk());var e=domain.getEntry(1,s.uid("student@example.test"));domain.save(1,new ApiController.DraftRequest("closed draft",(JsonNode)e.get("content"),((Number)e.get("revision")).intValue(),List.of()),s.uid("student@example.test"));mvc.perform(post("/api/entries/1/submissions").with(user("student@example.test")).with(csrf()).header("Idempotency-Key","expired-new-version").contentType("application/json").content("{\"revision\":2}")).andExpect(status().isUnprocessableEntity());}
 @Test void cannotCreateNewEntryAfterDeadline()throws Exception {long id=s.insert("INSERT INTO assignment(course_id,title,requirements,due_at,rubric_version,created_at) VALUES(1,'closed','test',?,'four-dim-v1',?)",Instant.now().minusSeconds(60).toString(),Store.now());mvc.perform(post("/api/assignments/"+id+"/entries").with(user("student@example.test")).with(csrf())).andExpect(status().isUnprocessableEntity());assertEquals(0,s.db.queryForObject("SELECT COUNT(*) FROM entry WHERE assignment_id=?",Integer.class,id));}
 @Test void reviewQueueShowsOnlyOwnDraftMetadata()throws Exception {otherTeacher();save(2,draft(0,0,"do not leak"));String own=mvc.perform(get("/api/courses/1/review-queue").with(user("teacher@example.test"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertFalse(own.contains("do not leak"));var ownRows=json.readTree(own);assertTrue(java.util.stream.StreamSupport.stream(ownRows.spliterator(),false).anyMatch(n->!n.path("review_draft_updated_at").isNull()));var other=json.readTree(mvc.perform(get("/api/courses/1/review-queue").with(user("teacher2@example.test"))).andReturn().getResponse().getContentAsString());for(var n:other)assertTrue(n.path("review_draft_updated_at").isNull());}

}
